local function continentIndex(name)
    local row = GameInfo.Continents[name]
    if row and row.Index ~= nil then return row.Index end
    for r in GameInfo.Continents() do
        if r.ContinentType == name then return r.Index end
    end
    return nil
end

local function RepairContinents()
    local w, h = Map.GetGridSize()
    if w ~= 166 or h ~= 82 then
        print("NolyRepairContinents: skipped, map is " .. tostring(w) .. "x" .. tostring(h))
        return
    end

    local fixed, skipped, errors = 0, 0, 0
    for name, ids in pairs(groups) do
        local ci = continentIndex(name)
        if ci == nil then
            print("NolyRepairContinents: missing continent " .. tostring(name))
        else
            for _, id in ipairs(ids) do
                local plot = Map.GetPlotByIndex(id)
                if plot and not plot:IsWater() then
                    if plot:GetContinentType() ~= ci then
                        local ok = pcall(function()
                            TerrainBuilder.SetContinentType(plot, ci)
                        end)
                        if ok then fixed = fixed + 1 else errors = errors + 1 end
                    end
                else
                    skipped = skipped + 1
                end
            end
        end
    end
    print("NolyRepairContinents: fixed " .. fixed .. ", skipped " .. skipped .. ", errors " .. errors)
end

Events.LoadScreenClose.Add(RepairContinents)
